import{_ as i,a0 as l,w as p,s,I as o,x as t,a1 as a,A as r,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"Linux 內核測試和調試（4） | LCTT x X-CMD","titleTemplate":false,"description":"Linux 內核測試和調試（4） | LCTT (201408) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 內核測試和調試（4） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 內核測試和調試（4） | LCTT (201408) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201408/20140718 Linux Kernel Testing and Debugging 4","title":"Linux 內核測試和調試（4）","tag":"201408","desc":""},"relativePath":"201408/20140718 Linux Kernel Testing and Debugging 4.md","filePath":"[post].md"}'),u={name:"201408/20140718 Linux Kernel Testing and Debugging 4.md"},m={id:"autotest",tabindex:"-1"};function c(k,e,b,g,T,h){const n=l("Link");return p(),s("div",null,[e[23]||(e[23]=o("h1",{id:"linux-內核測試和調試-4",tabindex:"-1"},[t("Linux 內核測試和調試（4） "),o("a",{class:"header-anchor",href:"#linux-內核測試和調試-4","aria-label":"Permalink to “Linux 內核測試和調試（4）”"},"​")],-1)),e[24]||(e[24]=o("h3",{id:"自動測試工具",tabindex:"-1"},[t("自動測試工具 "),o("a",{class:"header-anchor",href:"#自動測試工具","aria-label":"Permalink to “自動測試工具”"},"​")],-1)),e[25]||(e[25]=o("p",null,"這裏列出一些能滿足不同需求的測試工具供你選擇。本小節只是簡單介紹個大概，並不提供詳細操作指南。",-1)),o("h4",m,[a(n,{href:"http://autotest.github.io/"},{default:r(()=>[...e[0]||(e[0]=[t("AuToTest",-1)])]),_:1}),e[1]||(e[1]=t()),e[2]||(e[2]=o("a",{class:"header-anchor",href:"#autotest","aria-label":"Permalink to “AuToTest”"},"​",-1))]),o("blockquote",null,[o("p",null,[e[4]||(e[4]=t("AuToTest 是一個全自動測試框架，存在的主要目的就是測試 Linux 內核，當然也可以用來測試其他東西，比如測試一塊新硬件是否能穩定工作。AuToTest 是開源軟件，以 GPL 方式授權，運行於 server-client 架構（即 C/S 架構）。你可以通過配置 server 端來對運行了 client 端的系統執行初始化、運行與監測工作，也可以自己在目標系統上讓 client 運行起來。另外你可以為這個測試框架添加測試用例，詳情請參考",-1)),a(n,{href:"https://github.com/autotest/autotest/wiki/WhitePaper"},{default:r(()=>[...e[3]||(e[3]=[t("AuToTest 白皮書",-1)])]),_:1}),e[5]||(e[5]=t("。",-1))])]),e[26]||(e[26]=d(`<h4 id="linaro-automated-validation-architecture" tabindex="-1">Linaro Automated Validation Architecture <a class="header-anchor" href="#linaro-automated-validation-architecture" aria-label="Permalink to “Linaro Automated Validation Architecture”">​</a></h4><blockquote><p>LAVA 自動測試框架用於自動安裝於運行測試。舉個例子：你在 LAVA 裏面只需運行幾個命令就可以跑 LTP（LCTT：Linux Test Project，中文是 Linux 測試計劃，SGI發起並由IBM負責維護，目的是為開源社區提供測試套件來驗證Linux的可靠性、健壯性和穩定性）。通過 LAVA 命令可以自動為你安裝 LTP 所需要的所有依賴包，下載源碼、編譯編碼、將 LTP 安裝到某個獨立的地方，方便卸載 LTP 時能移除所有二進制文件。安裝好 LTP 後，運行 LAVA 命令時添加 &#39;ltp&#39; 選項就可以運行 LTP 測試任務了，它會將測試結果以文件方式保存下來，文件名包含測試名稱、時間戳。這些測試結果可以留着供以後參考。這是個發現軟件退化（如果軟件退化了的話）的好方法。下面列出 LAVA 配合 LTP 使用的一些命令：</p></blockquote><p>顯示 LAVA 支持的測試列表：</p><pre><code>lava-test list-tests 
</code></pre><p>安裝測試套件：</p><pre><code>lava-test install ltp 
</code></pre><p>運行測試：</p><pre><code>lava-test run ltp 
</code></pre><p>查看結果：</p><pre><code>lava-test results show ltp-timestamp.0 
</code></pre><p>卸載測試套件：</p><pre><code>lava-test uninstall ltp 
</code></pre><h3 id="內核調試功能" tabindex="-1">內核調試功能 <a class="header-anchor" href="#內核調試功能" aria-label="Permalink to “內核調試功能”">​</a></h3><p>Linux 內核本身包含很多調試功能，比如 kmemcheck 和 kmemleak。</p><h4 id="kmemcheck" tabindex="-1">kmemcheck <a class="header-anchor" href="#kmemcheck" aria-label="Permalink to “kmemcheck”">​</a></h4><blockquote><p>kmemcheck 是一個動態檢查工具，可以檢測出一些未被初始化的內存（LCTT：內核態使用這些內存可能會造成系統崩潰）併發出警告。它的功能與 Valgrind 類似，只是 Valgrind 運行在用户態，而 kmemchecke 運行在內核態。編譯內核時加上 <code>CONFIG_KMEMCHECK</code> 選項打開 kmemcheck 調試功能。你可以閲讀 Documentation/kmemcheck.txt 來學習如何配置使用這個功能，以及如何看懂調試結果。</p></blockquote><h4 id="kmemleak" tabindex="-1">kmemleak <a class="header-anchor" href="#kmemleak" aria-label="Permalink to “kmemleak”">​</a></h4><blockquote><p>kmemleak 通過類似於垃圾收集器的功能來檢測內核是否有內存泄漏問題。而 kmemleak 與垃圾收集器的不同之處在於前者不會釋放孤兒目標（LCTT：不會再被使用的、應該被釋放而沒被釋放的內存區域），而是將它們打印到 /sys/kernel/debug/kmemleak 文件中。用户態的 Valgrind 也有一個類似的功能，使用 --leak-check 選項可以檢測並報錯內存泄漏問題，但並不釋放這個孤兒內存。編譯內核時使用 <code>CONFIG_DEBUG_KMEMLEAK</code> 選項打開 kmemcleak 調試功能。閲讀 Documentation/kmemleak.txt 來學習怎麼使用這個工具並讀懂調試結果。</p></blockquote><h3 id="內核調試接口" tabindex="-1">內核調試接口 <a class="header-anchor" href="#內核調試接口" aria-label="Permalink to “內核調試接口”">​</a></h3><p>Linux 內核通過配置選項、調試用的 API、接口和框架來支持動態或靜態的調試。我們現在就好好學習學習這些牛逼的功能，從靜態編譯選項開始講。</p><h3 id="調試配置選項-靜態編譯" tabindex="-1">調試配置選項：靜態編譯 <a class="header-anchor" href="#調試配置選項-靜態編譯" aria-label="Permalink to “調試配置選項：靜態編譯”">​</a></h3><p>大部分 Linux 內核以及內核模組都包含調試選項，你只要在編譯內核或內核模組的時候添加這個靜態調試選項，程序運行時後就會產生調試信息，並記錄在 dmesg 緩存中。</p><h3 id="調試的-api" tabindex="-1">調試的 API <a class="header-anchor" href="#調試的-api" aria-label="Permalink to “調試的 API”">​</a></h3>`,23)),o("p",null,[e[7]||(e[7]=d("調試 API 的一個很好的例子是 DMA-debug，用來調試驅動是否錯誤使用了 DMA 提供的 API。它會跟蹤每個設備的映射關係，檢測程序有沒有試圖為一些根本不存在的映射執行“取消映射”操作，檢測代碼建立 DMA 映射後可能產生的“映射丟失”的錯誤。內核配置選項 <code>CONFIG_HAVE_DMA_APT_DEBUG</code> 和 <code>CONFIG_DMA_API_DEBUG</code> 可以為內核提供這個功能。其中，<code>CONFIG_DMA_API_DEBUG</code> 選項啓用後，內核調用 DMA 的 API 的同時也會調用 Debug-dma 接口。舉例來説，當一個驅動調用 <code>dma_map_page()</code> 函數來映射一個 DMA 緩存時，<code>dma_map_page()</code> 會調用<code>debug_dma_map_page()</code> 函數來跟蹤這個緩存，直到驅動調用 <code>dma_unmap_page()</code> 來取消映射。詳細內容請參考",15)),a(n,{href:"http://events.linuxfoundation.org/sites/events/files/slides/Shuah_Khan_dma_map_error.pdf"},{default:r(()=>[...e[6]||(e[6]=[t("使用 DMA 調試 API 檢測潛在的數據污染和內存泄漏問題",-1)])]),_:1}),e[8]||(e[8]=t("。",-1))]),e[27]||(e[27]=d(`<h3 id="動態調試" tabindex="-1">動態調試 <a class="header-anchor" href="#動態調試" aria-label="Permalink to “動態調試”">​</a></h3><p>動態調試功能就是你可以決定在程序運行過程中是否要 <code>pr_debug()</code>, <code>dev_dbg()</code>, <code>print_hex_dump_debug()</code>, <code>print_hex_dump_bytes()</code> 這些函數正常運行起來。什麼意思？當程序運行過程中出現錯誤時，你可以指定程序打印有針對性的、詳細的調試信息。這功能牛逼極了，我們不再需要為了添加調試代碼定位一個問題，而重新編譯安裝內核。你可以指定 <code>CONDIF_DYNAMIC_DEBUG</code> 選項打開動態調試功能，然後通過 <code>/sys/kernel/debug/dynamic_debug/control</code> 接口指定要打印哪些調試日誌。下面分別列出代碼級別和模組級別打印日誌的操作方法：</p><p>讓 kernel/power/suspend.c 源碼第340行的 <code>pr_debug()</code> 函數打印日誌：</p><pre><code>echo &#39;file suspend.c line 340 +p&#39; &gt; /sys/kernel/debug/dynamic_debug/control
</code></pre><p>讓內核模組在加載過程中打開動態調試功能：</p><blockquote><p>使用 modprobe 命令加在模組時加上 dyndbg=&#39;plmft&#39; 選項。</p></blockquote><p>讓內核模組的動態調試功能在重啓後依然有效：</p><blockquote><p>編輯 /etc/modprobe.d/modname.conf 文件（沒有這個文件就創建一個），添加 dyndbg=&#39;plmft&#39; 選項。然而對於哪些通過 initramfs 加載的驅動來説，這個配置基本無效（LCTT：免費奉送點比較高級的知識哈。系統啓動時，需要先讓 initramfs 掛載一個虛擬的文件系統，然後再掛載啓動盤上的真實文件系統。這個虛擬文件系統裏面的文件是 initramfs 自己提供的，也就是説你在真實的文件系統下面配置了 /etc/modprobe.d/modname.conf 這個文件，initramfs 是壓根不去理會的。站在內核驅動的角度看：如果內核驅動在 initramfs 過程中被加載到內核，這個驅動讀取到的 /etc/modprobe.d/modname.conf 是 initramfs 提供的，而不是你編輯的那個。所以會有上述“寫了配置文件後重啓依然無效”的結論）。對於這種刁民，呃，刁驅動，我們需要修改 grub 配置文件，在 kernel 那一行添加 module.dyndbg=&#39;plmft&#39; 參數，這樣你的驅動就可以開機啓動動態調試功能了。</p></blockquote><p>想打印更詳細的調試信息，可以使用 <code>dynamic_debug.verbose=1</code> 選項。參考 Documentation/dynamic-debug-howto.txt 文件獲取更多信息。</p><h3 id="設置追蹤點" tabindex="-1">設置追蹤點 <a class="header-anchor" href="#設置追蹤點" aria-label="Permalink to “設置追蹤點”">​</a></h3><p>到目前為止，我們介紹了多種動態和靜態調試方法。靜態調試選項和靜態調試鈎子函數（比如 DMA Debug API）需要的編譯過程打開或關閉，導致了一個難過的事實：需要重新編譯安裝內核。而動態編譯功能省去了“重新編譯”這件麻煩事，但是也有不足的地方，就是調試代碼引入了條件變量，用於判斷是否打印調試信息。這種方法可以讓你在程序運行時決定是否打印日誌，但需要執行額外的判斷過程。“追蹤點”代碼只會在程序運行過程中使用“追蹤點”功能才會被觸發。也就是説，“追蹤點”代碼與上述説的兩種方法都不一樣。當用不到它時，它不會運行（LCTT：動態調試的話，代碼每次都需要查看下變量，然後判斷是否需要打印日誌；而“追蹤點”貌似利用某種觸發機制，不需要每次都去查看變量）。當你需要用到它時，程序的代碼會把“追蹤點”代碼包含進去。它不會添加任何條件變量來增加系統的運行負擔。</p>`,11)),o("p",null,[e[10]||(e[10]=t("詳細信息請參考",-1)),a(n,{href:"http://www.linuxjournal.com/content/july-2013-linux-kernel-news"},{default:r(()=>[...e[9]||(e[9]=[t("佈置追蹤代碼的小技巧",-1)])]),_:1}),e[11]||(e[11]=t("。",-1))]),e[28]||(e[28]=d(`<h3 id="追蹤點-的原理" tabindex="-1">“追蹤點”的原理 <a class="header-anchor" href="#追蹤點-的原理" aria-label="Permalink to ““追蹤點”的原理”">​</a></h3><p>追蹤點使用“跳躍標籤”，這是一種使用分支跳轉的編碼修正（code modification）技術。</p><p>當關閉追蹤點的時候，其偽代碼看起來時這樣的：</p><pre><code>[ code1 ]
nop
back:
[ code2 ]
return;
tracepoint:
[ tracepoint code ]
jmp back;
</code></pre><p>當打開追蹤點的時候，其偽代碼看起來時這樣的：（注意追蹤點代碼出現的位置）</p><pre><code>[ code1 ]
jmp tracepoint
back:
[ code2 ]
return;
tracepoint:
[ tracepoint code ]
jmp back;
</code></pre><p>（LCTT：咳咳，解釋解釋上面兩段偽代碼吧，能看懂的大神請忽略這段註釋。不使用追蹤點時，代碼運行過程是：code1-&gt;code2-&gt;return結束；使用追蹤點時，代碼運行過程是：code1-&gt;跳到tracepoint code執行調試代碼-&gt;跳回code2-&gt;return結束。兩段代碼的唯一區別就是第二行，前者為 nop（不做任何操作），後者為 jmp tracepoint （跳到調試代碼）。）</p><h3 id="linux-電源管理子系統的測試" tabindex="-1">Linux 電源管理子系統的測試 <a class="header-anchor" href="#linux-電源管理子系統的測試" aria-label="Permalink to “Linux 電源管理子系統的測試”">​</a></h3><p>使用靜態調試、動態調試和追蹤調試技術，我們來跑一下磁盤的電源管理測試。當系統被掛起時，內核會為磁盤創建一個休眠鏡像，使磁盤進入休眠模式，當系統重新被喚醒時，內核又利用這個休眠鏡像重新喚醒磁盤。</p><p>設置掛起設備與喚醒設備需要的時間：</p><pre><code>echo 1 &gt; /sys/power/pm_print_times
</code></pre><p>以 reboot 模式掛起磁盤：</p><pre><code>echo reboot &gt; /sys/power/disk
echo disk &gt; /sys/power/state
</code></pre><p>以 shutdown 模式掛起磁盤 —— 與 reboot 模式一樣，只是重新喚醒磁盤的話還需要電源提供。</p><pre><code>echo shutdown &gt; /sys/power/disk
echo disk &gt; /sys/power/state
</code></pre><p>以 platform 模式掛起磁盤 —— 能測試更多內容，比如 BIOS 掛起和喚醒，會涉及到 ACPI 功能。我們推薦你使用這種方式，把 BIOS 也拉下水陪你玩掛起和喚醒遊戲。</p><pre><code>echo platform &gt; /sys/power/disk
echo disk &gt; /sys/power/state
</code></pre><hr>`,18)),o("p",null,[e[13]||(e[13]=t("via:",-1)),a(n,{href:"http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,3"},{default:r(()=>[...e[12]||(e[12]=[t("http://www.linuxjournal.com/content/linux-kernel-testing-and-debugging?page=0,3",-1)])]),_:1})]),o("p",null,[e[16]||(e[16]=t("譯者：",-1)),a(n,{href:"https://github.com/bazz2"},{default:r(()=>[...e[14]||(e[14]=[t("bazz2",-1)])]),_:1}),e[17]||(e[17]=t(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:r(()=>[...e[15]||(e[15]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[20]||(e[20]=t("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...e[18]||(e[18]=[t("LCTT",-1)])]),_:1}),e[21]||(e[21]=t(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:r(()=>[...e[19]||(e[19]=[t("Linux中國",-1)])]),_:1}),e[22]||(e[22]=t(" 榮譽推出",-1))])])}const A=i(u,[["render",c]]);export{f as __pageData,A as default};
